// Fit a complete sequence to the requested runtime while retaining relative pacing.
function allocateShotDurations(weights,total){
 const n=weights.length,target=Math.round(total*10);if(!n||target<n*5)throw Error('目标总时长与镜头数量不匹配，每镜至少需0.5秒');
 let free=weights.map((_,i)=>i),remaining=total,values=Array(n).fill(0);
 while(free.length){const sum=free.reduce((s,i)=>s+weights[i],0),proposed=Object.fromEntries(free.map(i=>[i,remaining*weights[i]/sum])),clamped=free.filter(i=>proposed[i]<.5);if(!clamped.length){for(const i of free)values[i]=remaining*weights[i]/sum;break;}for(const i of clamped){values[i]=.5;remaining-=values[i];}free=free.filter(i=>!clamped.includes(i));}
 const ticks=values.map(x=>Math.max(5,Math.floor(x*10+1e-7)));let missing=target-ticks.reduce((a,b)=>a+b,0);const order=values.map((x,i)=>i).sort((a,b)=>(values[b]*10-ticks[b])-(values[a]*10-ticks[a]));
 while(missing>0)for(const i of order)if(missing){ticks[i]++;missing--;}
 return ticks.map(x=>x/10);
}

function briefTimingSummary(b){if(b.shotControlMode==='auto'||b.customShotTiming===false)return '由 AI 自己调整：将按剧情起承转合、对白密度与镜头节奏自动决定最佳分镜数量与总时长（已解除镜数与秒数上限）。';if(!Number.isInteger(b.shotCount)||b.shotCount<1)return '请填写大于等于 1 的分镜数量（整数）';const count=b.shotCountMode==='max'?'最多 '+b.shotCount+' 镜':'共 '+b.shotCount+' 镜';if(b.timingMode==='fixed'){if(!Number.isFinite(b.fixedDuration)||b.fixedDuration<0.5)return count+'，请填写每镜不少于 0.5 秒的有效时长';return count+'，每镜 '+b.fixedDuration+' 秒，'+(b.shotCountMode==='max'?'总长不超过 ':'总长 ')+Math.round(b.shotCount*b.fixedDuration*10)/10+' 秒';}if(b.timingMode==='within'){if(!Number.isFinite(b.maxMinutes)||b.maxMinutes<0.1)return count+'，请填写不小于 0.1 分钟的目标上限';const note=b.maxMinutes*60<b.shotCount*0.5?'（提示：按每镜最少 0.5 秒计，建议延长时间）':'';return count+'，控制在 '+b.maxMinutes+' 分钟内，讲完即可，不必填满'+note;}if(!Number.isFinite(b.duration)||b.duration<0.5)return count+'，请填写不小于 0.5 秒的总时长';const note=b.duration<b.shotCount*0.5?'（提示：需满足每镜至少 0.5 秒，请延长总时长）':'';return count+'，AI 在 '+b.duration+' 秒内分配节奏'+note;}

